import React, { useState } from 'react';
import { projects } from '../data/mock';

// Tech-themed fallback images per category
const categoryImages = {
    Tools: 'https://images.unsplash.com/photo-1518432031352-d6fc5c10da5a?w=800&auto=format&fit=crop&q=60',
    Scripts: 'https://images.unsplash.com/photo-1629904853716-f0bc54eea481?w=800&auto=format&fit=crop&q=60',
    Apps: 'https://images.unsplash.com/photo-1555099962-4199c345e5dd?w=800&auto=format&fit=crop&q=60',
};

const categoryColors = {
    Tools:   { text: 'text-primary',      bg: 'bg-primary/15',     border: 'border-primary/30' },
    Scripts: { text: 'text-tertiary',     bg: 'bg-tertiary/15',    border: 'border-tertiary/30' },
    Apps:    { text: 'text-secondary-dim',bg: 'bg-secondary-dim/10', border: 'border-secondary-dim/30' },
};

const ProjectCard = ({ project }) => {
    const clr = categoryColors[project.category] || categoryColors.Tools;
    const imgSrc = project.image && !project.image.includes('photo-1743385779347')
        ? project.image
        : categoryImages[project.category] || categoryImages.Tools;

    return (
        <div className="group relative bg-surface-container-high rounded-2xl overflow-hidden border border-white/5 flex flex-col hover:border-white/10 transition-all duration-500 hover:-translate-y-1">
            {/* Image header */}
            <div className="aspect-[16/9] relative overflow-hidden bg-surface-container-highest">
                <img
                    alt={project.title}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 opacity-70 group-hover:opacity-90"
                    src={imgSrc}
                    onError={(e) => { e.target.src = categoryImages.Tools; }}
                />
                <div className="absolute inset-0 bg-gradient-to-t from-surface-container-high via-surface-container-high/40 to-transparent" />

                {/* Category badge overlaid on image */}
                <div className="absolute top-4 left-4">
                    <span className={`text-[10px] font-bold uppercase tracking-widest px-2.5 py-1 rounded-full border ${clr.bg} ${clr.text} ${clr.border}`}>
                        {project.category}
                    </span>
                </div>
            </div>

            {/* Content */}
            <div className="p-6 flex flex-col flex-grow">
                <h3 className="text-xl font-bold text-on-surface mb-3 leading-tight">
                    {project.title}
                </h3>
                <p className="text-on-surface-variant text-sm leading-relaxed mb-5 flex-grow line-clamp-3">
                    {project.description}
                </p>

                {/* Tech stack */}
                {project.techStack && project.techStack.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 mb-5">
                        {project.techStack.slice(0, 5).map((tech, idx) => (
                            <span key={idx} className="text-[11px] px-2.5 py-1 rounded-md bg-surface-container-highest/80 border border-white/5 text-on-surface-variant">
                                {tech}
                            </span>
                        ))}
                        {project.techStack.length > 5 && (
                            <span className="text-[11px] px-2 py-1 text-on-surface-variant opacity-60">
                                +{project.techStack.length - 5}
                            </span>
                        )}
                    </div>
                )}

                {/* Actions */}
                <div className="flex items-center gap-4 mt-auto pt-4 border-t border-white/5">
                    {project.githubUrl ? (
                        <a
                            href={project.githubUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-2 text-sm font-semibold text-primary hover:text-primary-container transition-colors group/link"
                        >
                            <span className="material-symbols-outlined text-[16px]">code</span>
                            Source Code
                            <span className="material-symbols-outlined text-[14px] opacity-0 group-hover/link:opacity-100 -translate-x-1 group-hover/link:translate-x-0 transition-all">arrow_forward</span>
                        </a>
                    ) : (
                        <span className="inline-flex items-center gap-1.5 text-sm text-on-surface-variant/50">
                            <span className="material-symbols-outlined text-[16px]">lock</span>
                            Private Project
                        </span>
                    )}
                    {project.liveUrl && (
                        <a
                            href={project.liveUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="ml-auto inline-flex items-center gap-1.5 text-sm text-on-surface-variant hover:text-on-surface transition-colors"
                        >
                            <span className="material-symbols-outlined text-[16px]">open_in_new</span>
                            Live
                        </a>
                    )}
                </div>
            </div>
        </div>
    );
};

const ProjectsShowcase = () => {
    const featured = projects.filter(p => p.featured);
    const rest = projects.filter(p => !p.featured);

    return (
        <section className="py-24 px-6 max-w-7xl mx-auto" id="projects">
            <div className="text-center mb-16">
                <h2 className="font-headline text-4xl md:text-5xl font-extrabold mb-4">
                    Featured <span className="text-gradient">Innovations</span>
                </h2>
                <p className="text-on-surface-variant max-w-2xl mx-auto text-base">
                    A collection of applications, tools, and scripts I've built to solve real-world problems.
                </p>
            </div>

            {/* Featured grid — first 2 side by side */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                {featured.slice(0, 2).map((project) => (
                    <ProjectCard key={project.id} project={project} />
                ))}
            </div>

            {/* Remaining projects in a 3-col grid */}
            {(featured.slice(2).length > 0 || rest.length > 0) && (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
                    {[...featured.slice(2), ...rest].map((project) => (
                        <ProjectCard key={project.id} project={project} />
                    ))}
                </div>
            )}
        </section>
    );
};

export default ProjectsShowcase;
